/*
 * sw.js — service worker (offline support, installable PWA).
 * Generated by scripts/build.mjs, which fills in the build stamp and the precache list.
 *
 * Strategy
 *  - Precache the app shell (HTML, CSS, JS chunks, fonts, icons) per build.
 *  - repos.json / story.json: NETWORK FIRST (fresh daily data), cache fallback offline.
 *  - Other same-origin GET requests: cache first, then network.
 *  - Cross-origin (GitHub README fetches, avatars): never intercepted.
 *  - Old caches are deleted on activate (they belong to this site only).
 */
const VERSION = 'mw4l93xe';
const CACHE = `malik-v4-${VERSION}`;
const PRECACHE = ["./","index.html","assets/app.css","assets/app.js","assets/chunk-NWO2PDU3.js","assets/chunk-FKPC33MA.js","assets/chunk-W4JJ2LD5.js","assets/chunk-VS2Q4U4D.js","assets/chunk-3QCL7CJV.js","assets/chunk-2GT2IU5A.js","assets/chunk-O2XFH626.js","assets/fonts/inter-tight-latin-wght-normal.woff2","assets/fonts/jetbrains-mono-latin-wght-normal.woff2","favicon.svg","manifest.webmanifest","icons/apple-touch-icon.png","icons/icon-192.png","icons/icon-512.png","icons/icon-maskable-512.png"];
const DATA = /\/(repos|story)\.json$/;

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((c) => c.addAll(PRECACHE)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('malik-v4-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  if (DATA.test(url.pathname)) {
    event.respondWith(
      fetch(req)
        .then((res) => {
          if (res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(url.pathname, copy)); }
          return res;
        })
        .catch(() => caches.match(url.pathname)),
    );
    return;
  }

  if (req.mode === 'navigate') {
    event.respondWith(fetch(req).catch(() => caches.match('./').then((r) => r || caches.match('index.html'))));
    return;
  }

  event.respondWith(
    caches.match(req, { ignoreSearch: true }).then((hit) => hit || fetch(req).then((res) => {
      if (res.ok && res.type === 'basic') { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(req, copy)); }
      return res;
    })),
  );
});
